902	        private void maybeUpdateCopiedOffset(UnifiedLog log) throws RemoteStorageException {
903	            if (copiedOffsetOption.isEmpty()) {
904	                // This is found by traversing from the latest leader epoch from leader epoch history and find the highest offset
905	                // of a segment with that epoch copied into remote storage. If it can not find an entry then it checks for the
906	                // previous leader epoch till it finds an entry, If there are no entries till the earliest leader epoch in leader
907	                // epoch cache then it starts copying the segments from the earliest epoch entry's offset.
908	                copiedOffsetOption = Optional.of(findHighestRemoteOffset(topicIdPartition, log));
909	                logger.info("Found the highest copiedRemoteOffset: {} for partition: {} after becoming leader", copiedOffsetOption, topicIdPartition);
910	                copiedOffsetOption.ifPresent(offsetAndEpoch ->  log.updateHighestOffsetInRemoteStorage(offsetAndEpoch.offset()));
911	            }
912	        }
913	
914	        /**
915	         *  Segments which match the following criteria are eligible for copying to remote storage:
916	         *  1) Segment is not the active segment and
917	         *  2) Segment end-offset is less than the last-stable-offset as remote storage should contain only
918	         *     committed/acked messages
919	         * @param log The log from which the segments are to be copied
920	         * @param fromOffset The offset from which the segments are to be copied
921	         * @param lastStableOffset The last stable offset of the log
922	         * @return candidate log segments to be copied to remote storage
923	         */
924	        List<EnrichedLogSegment> candidateLogSegments(UnifiedLog log, Long fromOffset, Long lastStableOffset) {
925	            List<EnrichedLogSegment> candidateLogSegments = new ArrayList<>();
926	            List<LogSegment> segments = log.logSegments(fromOffset, Long.MAX_VALUE);
927	            if (!segments.isEmpty()) {
928	                for (int idx = 1; idx < segments.size(); idx++) {
929	                    LogSegment previousSeg = segments.get(idx - 1);
930	                    LogSegment currentSeg = segments.get(idx);
931	                    if (currentSeg.baseOffset() <= lastStableOffset) {
932	                        candidateLogSegments.add(new EnrichedLogSegment(previousSeg, currentSeg.baseOffset()));
933	                    }
934	                }
935	                // Discard the last active segment
936	            }
937	            return candidateLogSegments;
938	        }
